.ventursim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e7ecf5;
    background: radial-gradient(1200px 500px at 80% -10%, #1b2a4a 0%, #0c1426 55%, #070b16 100%);
    border-radius: 18px;
}

.ventursim-container * {
    box-sizing: border-box;
}

.ventursim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #102a4c 0%, #14365f 55%, #0e7c66 130%);
    color: #f3f7ff;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid rgba(120, 180, 255, 0.18);
    box-shadow: 0 12px 34px rgba(4, 10, 24, 0.55);
}

.ventursim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    background: linear-gradient(90deg, #6ee7b7 0%, #67c8ff 100%);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
}

.ventursim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #9fe7cf;
    background: rgba(110, 231, 183, 0.12);
    border: 1px solid rgba(110, 231, 183, 0.22);
    padding: 5px 14px;
    border-radius: 999px;
}

.ventursim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cdd9ef;
}

.ventursim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #b9c6e0;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.ventursim-period-counter #currentDay,
.ventursim-period-counter #maxPeriods {
    font-weight: 800;
    color: #6ee7b7;
}

.ventursim-round-name {
    background: rgba(103, 200, 255, 0.14);
    color: #8fd4ff;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid rgba(103, 200, 255, 0.25);
}

.ventursim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffcaa0;
    background: rgba(255, 138, 76, 0.13);
    border: 1px solid rgba(255, 138, 76, 0.28);
    padding: 4px 12px;
    border-radius: 999px;
}

.ventursim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.ventursim-status-card {
    background: rgba(22, 34, 58, 0.78);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid rgba(120, 160, 220, 0.16);
    box-shadow: 0 6px 18px rgba(4, 10, 24, 0.4);
    border-top: 4px solid #67c8ff;
    backdrop-filter: blur(6px);
}

.ventursim-card-learning { border-top-color: #6ee7b7; }
.ventursim-card-traction { border-top-color: #67c8ff; }
.ventursim-card-runway { border-top-color: #c9a6ff; }
.ventursim-card-budget { border-top-color: #ffc36e; }

.ventursim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    font-weight: 700;
    color: #8ea2c4;
}

.ventursim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #eef3fb;
}

.ventursim-card-learning .ventursim-value { color: #6ee7b7; }
.ventursim-card-traction .ventursim-value { color: #67c8ff; }
.ventursim-card-runway .ventursim-value { color: #c9a6ff; }
.ventursim-card-budget .ventursim-value { color: #ffc36e; }

.ventursim-sublabel {
    font-size: 0.76rem;
    color: #7e92b4;
    line-height: 1.35;
}

.ventursim-traction-hit .ventursim-value { color: #6ee7b7; }

.ventursim-runway-low { border-top-color: #ff6b6b; }
.ventursim-runway-low .ventursim-value { color: #ff8585; }

.ventursim-budget-over { border-top-color: #ff6b6b; }
.ventursim-budget-over .ventursim-value { color: #ff8585; }

.ventursim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: linear-gradient(90deg, #102036 0%, #14365f 100%);
    color: #eaf2ff;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border: 1px solid rgba(120, 160, 220, 0.18);
}

.ventursim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #ffc36e;
}

.ventursim-briefing {
    display: flex;
    gap: 14px;
    background: rgba(20, 31, 54, 0.82);
    border-left: 5px solid #6ee7b7;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(4, 10, 24, 0.35);
}

.ventursim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.ventursim-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #aef0d6;
    margin-bottom: 6px;
}

.ventursim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.58;
    color: #cdd9ef;
}

.ventursim-briefing-text strong { color: #6ee7b7; }
.ventursim-briefing-text em { color: #ffcaa0; font-style: italic; }

.ventursim-controls {
    background: rgba(18, 28, 49, 0.86);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid rgba(120, 160, 220, 0.16);
    box-shadow: 0 6px 18px rgba(4, 10, 24, 0.4);
}

.ventursim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #eef3fb;
    border-bottom: 2px solid rgba(120, 160, 220, 0.18);
    padding-bottom: 8px;
}

.ventursim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #c7d4ec;
    margin: 16px 0 6px;
}

.ventursim-container select,
.ventursim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid rgba(120, 160, 220, 0.30);
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0f1c33;
    color: #e7ecf5;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.ventursim-container select:focus,
.ventursim-container input[type="number"]:focus {
    outline: none;
    border-color: #6ee7b7;
    box-shadow: 0 0 0 3px rgba(110, 231, 183, 0.18);
}

.ventursim-container select option {
    background-color: #0f1c33;
    color: #e7ecf5;
}

.ventursim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #6ee7b7;
}

.ventursim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #8fd4ff;
    margin-top: 4px;
}

.ventursim-range-readout span:last-child {
    color: #6ee7b7;
    font-weight: 800;
}

.ventursim-hint {
    font-size: 0.8rem;
    color: #7e92b4;
    margin-top: 4px;
    line-height: 1.45;
}

.ventursim-container .btn {
    margin-top: 20px;
    font-weight: 700;
}

.ventursim-container .btn-primary {
    background: linear-gradient(135deg, #0e9e74 0%, #2c8fd6 100%);
    border: none;
    color: #02131c;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(14, 158, 116, 0.30);
}

.ventursim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.ventursim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: rgba(120, 160, 220, 0.35);
    color: #9fb0d2;
    background: transparent;
}

.ventursim-coach {
    background: linear-gradient(135deg, #0c1830 0%, #122a4a 100%);
    color: #dce6fa;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(110, 231, 183, 0.18);
    box-shadow: 0 8px 22px rgba(4, 10, 24, 0.45);
}

.ventursim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #6ee7b7;
    margin-bottom: 8px;
}

.ventursim-coach-body {
    font-size: 0.95rem;
    line-height: 1.58;
}

.ventursim-coach-body strong { color: #ffd98a; }
.ventursim-coach-body em { color: #ffb59a; font-style: italic; }

.ventursim-history,
.ventursim-chart {
    background: rgba(18, 28, 49, 0.86);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(120, 160, 220, 0.16);
    box-shadow: 0 6px 18px rgba(4, 10, 24, 0.4);
}

.ventursim-history h3,
.ventursim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #eef3fb;
}

.ventursim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #cdd9ef;
}

.ventursim-container table#usfHistoryTable th {
    background: rgba(103, 200, 255, 0.10);
    color: #aef0d6;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid rgba(120, 160, 220, 0.22);
}

.ventursim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid rgba(120, 160, 220, 0.12);
}

.ventursim-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(103, 200, 255, 0.05);
}

.ventursim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .ventursim-container {
        padding: 14px;
    }
    .ventursim-header h1 {
        font-size: 1.75rem;
    }
    .ventursim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .ventursim-value {
        font-size: 2rem;
    }
    .ventursim-clock {
        margin-left: 0;
    }
    .ventursim-period-counter {
        font-size: 0.88rem;
    }
    .ventursim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .ventursim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion modal (append-only, dark-on-light) ===== */
.ventursim-completion { color:#20293a; font-size:0.95rem; }
.ventursim-cm-head { text-align:center; margin-bottom:16px; }
.ventursim-cm-score { font-size:3.2rem; font-weight:800; line-height:1; color:#3d5aa8; }
.ventursim-cm-score-max { font-size:1.2rem; font-weight:600; color:#8093c4; }
.ventursim-cm-grade { font-size:1.2rem; font-weight:700; margin-top:6px; color:#141d33; }
.ventursim-cm-badge { display:inline-block; margin-left:6px; padding:2px 10px; border-radius:999px; font-size:0.78rem; font-weight:700; vertical-align:middle; }
.ventursim-cm-yes { background:rgba(61,90,168,0.14); color:#33509a; border:1px solid rgba(61,90,168,0.5); }
.ventursim-cm-no { background:rgba(201,138,22,0.16); color:#8a6a1f; border:1px solid rgba(201,138,22,0.5); }
.ventursim-cm-fail { background:rgba(192,57,43,0.12); color:#b0392b; border:1px solid rgba(192,57,43,0.45); }
.ventursim-cm-metrics { display:flex; flex-wrap:wrap; gap:10px; justify-content:center; margin:12px 0 16px; }
.ventursim-cm-metric { flex:1 1 110px; min-width:100px; background:rgba(20,29,51,0.06); border:1px solid rgba(20,29,51,0.16); border-radius:10px; padding:10px 8px; text-align:center; }
.ventursim-cm-mv { display:block; font-size:1.4rem; font-weight:800; color:#1f2a44; }
.ventursim-cm-ml { display:block; font-size:0.72rem; margin-top:4px; color:#5a6884; text-transform:uppercase; letter-spacing:0.03em; }
.ventursim-cm-insights-title { font-weight:700; margin:8px 0 6px; color:#141d33; }
.ventursim-cm-insights { margin:0; padding-left:20px; }
.ventursim-cm-insights li { margin:4px 0; color:#2b3852; }

