(function() {
    'use strict';

    class VentureAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Startup Inside`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (budget in R$ millions).
            this.BUDGET_CAP = 9.0;           // R$9M ring-fenced fund
            this.START_RUNWAY = 9.0;         // 9 months, hard limit
            this.MONTHLY_BURN = 1.0;         // ~R$1.0M / month full team
            this.PILOT_BAR = 35;             // ≥35% paid-pilot conversion milestone
            this.SERIES_A = 25;              // R$25M internal growth round

            // Concept truths.
            this.TRUE_IDEA = `devolveja`;    // underserved, fits core, cheap to validate, reachable in runway
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    learning: 8,
                    traction: 5,
                    runway: this.START_RUNWAY,
                    budgetUsed: 0,
                    fundedIdea: ``,
                    builtFull: false,
                    vanity: false,
                    sunkDriven: false,
                    burnedOut: false,
                    killed: false,
                    rotaDrag: false,
                    learningHistory: [8],
                    tractionHistory: [5],
                    runwayHistory: [this.START_RUNWAY],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / classic-wrong-leaning mix,
                // NOT the textbook play — a click-through must not auto-win.
                state.decisions = {
                    idea: `entregaflex`,
                    basis: `sponsor`,
                    assumption: `build`,
                    rigor: 50,
                    mvp: `fullbuild`,
                    evidence: `signups`,
                    spend: 3.0,
                    focus: `broad`,
                    read: `vanity`,
                    decision: `persevere`,
                    sunk: 50,
                    reserve: 2,
                    plan: `scaleanyway`,
                    pitch: `demo`,
                    sponsor: `split`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const idea = document.getElementById(`ideaInput`);
                const basis = document.getElementById(`basisInput`);
                const assume = document.getElementById(`assumptionInput`);
                const rigor = document.getElementById(`rigorInput`);
                if (idea) decisions.idea = idea.value;
                if (basis) decisions.basis = basis.value;
                if (assume) decisions.assumption = assume.value;
                if (rigor) decisions.rigor = parseInt(rigor.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const mvp = document.getElementById(`mvpInput`);
                const ev = document.getElementById(`evidenceInput`);
                const spend = document.getElementById(`spendInput`);
                const focus = document.getElementById(`focusInput`);
                if (mvp) decisions.mvp = mvp.value;
                if (ev) decisions.evidence = ev.value;
                if (focus) decisions.focus = focus.value;
                if (spend) decisions.spend = parseFloat(spend.value);
                if (!Number.isFinite(decisions.spend) || decisions.spend < 0) {
                    warn(`warn_spend_negative`); return false;
                }
                const remaining = this.BUDGET_CAP - (state.domainState.budgetUsed || 0);
                if (decisions.spend > remaining + 0.0001) {
                    warn(`warn_spend_overcap`); return false;
                }
            } else if (round === 3) {
                const read = document.getElementById(`readInput`);
                const dec = document.getElementById(`decisionInput`);
                const sunk = document.getElementById(`sunkInput`);
                const reserve = document.getElementById(`reserveInput`);
                if (read) decisions.read = read.value;
                if (dec) decisions.decision = dec.value;
                if (sunk) decisions.sunk = parseInt(sunk.value, 10);
                if (reserve) decisions.reserve = parseFloat(reserve.value);
                if (!Number.isFinite(decisions.sunk) || decisions.sunk < 0 || decisions.sunk > 100) {
                    warn(`warn_sunk_range`); return false;
                }
                if (!Number.isFinite(decisions.reserve) || decisions.reserve < 0) {
                    warn(`warn_reserve_negative`); return false;
                }
            } else if (round === 4) {
                const plan = document.getElementById(`planInput`);
                const pitch = document.getElementById(`pitchInput`);
                const sp = document.getElementById(`sponsorInput`);
                const cv = document.getElementById(`convictionInput`);
                if (plan) decisions.plan = plan.value;
                if (pitch) decisions.pitch = pitch.value;
                if (sp) decisions.sponsor = sp.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let learningDelta = 0, tractionDelta = 0;
            let burn = this.MONTHLY_BURN;   // baseline team burn this round (months of runway)
            let spend = 0;                  // R$M committed against the budget cap this round
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Round 1 — Diagnose & select the idea.
                ds.fundedIdea = d.idea;

                // Idea fit to runway + validation reachability (Common Errors 1 & 2).
                if (d.idea === this.TRUE_IDEA) {
                    learningDelta += 9; tractionDelta += 4; coachKey = `coach_r1_devolveja`;
                } else if (d.idea === `entregaflex`) {
                    // Sponsor's safe pick on one verbal "interest" — venture-worthiness in doubt.
                    learningDelta += 1; tractionDelta += 2; coachKey = `coach_r1_entregaflex`;
                } else if (d.idea === `rotasmart`) {
                    // Biggest TAM, but a 9–12 month enterprise sales cycle outruns the 9-month runway.
                    // The long sales cycle keeps eating runway every round, not just once.
                    learningDelta -= 4; tractionDelta -= 6; burn += 0.5;
                    ds.rotaDrag = true;
                    coachKey = `coach_r1_rotasmart`;
                }

                // Basis of the choice — evidence vs market-size seduction vs sponsor pressure.
                if (d.basis === `criteria`) {
                    learningDelta += 8;
                    if (d.idea === this.TRUE_IDEA) coachKey = `coach_r1_sharp`;
                } else if (d.basis === `market`) {
                    learningDelta -= 5; coachKey = (d.idea === `rotasmart`) ? `coach_r1_rotasmart` : `coach_r1_market`;
                } else if (d.basis === `sponsor`) {
                    learningDelta -= 6; tractionDelta -= 2; coachKey = `coach_r1_sponsor`;
                }

                // Riskiest assumption — willingness-to-pay is the one to test first.
                if (d.assumption === `wtp`) {
                    learningDelta += 5;
                } else if (d.assumption === `build`) {
                    learningDelta -= 3;
                } else {
                    learningDelta -= 7; coachKey = `coach_r1_noassumption`;
                }

                // Selection discipline.
                if (d.rigor >= 60) { learningDelta += 4; }
                else if (d.rigor <= 25) { learningDelta -= 5; }

                summaryKey = (d.idea === this.TRUE_IDEA && d.basis === `criteria` && d.assumption === `wtp`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Round 2 — Scope the MVP (Common Error 3: building before validating).
                spend = d.spend;

                // Build approach: concierge/fake-door maximises learning per R$ and preserves runway.
                if (d.mvp === `concierge`) {
                    learningDelta += 11; tractionDelta += 4; coachKey = `coach_r2_concierge`;
                } else if (d.mvp === `thin`) {
                    learningDelta += 5; tractionDelta += 1; coachKey = `coach_r2_thin`;
                } else if (d.mvp === `fullbuild`) {
                    // Building the real platform before validation: ~R$4.2M and ~4 months, eats the runway.
                    ds.builtFull = true;
                    learningDelta -= 8; tractionDelta += 2;
                    burn += 3.0;
                    if (spend < 4.0) spend = 4.2;   // a full build cannot be done on a discovery budget
                    coachKey = `coach_r2_fullbuild`;
                }

                // Evidence definition — falsifiable paid-pilot criteria vs vanity sign-ups.
                if (d.evidence === `paidpilot`) {
                    learningDelta += 8; tractionDelta += 6;
                } else if (d.evidence === `signups`) {
                    learningDelta -= 3; tractionDelta += 1; ds.vanity = true; coachKey = `coach_r2_signups`;
                } else if (d.evidence === `opinion`) {
                    learningDelta -= 6; ds.vanity = true; coachKey = `coach_r2_opinion`;
                }

                // Validation-sprint budget: the R$0.9–1.6M band is disciplined; too little learns nothing,
                // too much (when not forced by a full build) wastes runway.
                if (!ds.builtFull) {
                    if (spend >= 0.9 && spend <= 1.6) { learningDelta += 5; }
                    else if (spend < 0.9) { learningDelta -= 5; coachKey = `coach_r2_underspend`; }
                    else if (spend > 2.5) { learningDelta -= 4; coachKey = `coach_r2_overspend`; }
                }

                // Hypothesis focus — one riskiest assumption vs scatter.
                if (d.focus === `riskiest`) { learningDelta += 5; }
                else { learningDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r2_broad`; }

                summaryKey = (d.mvp === `concierge` && d.evidence === `paidpilot` && d.focus === `riskiest`) ? `sum_r2_good` : (d.mvp === `fullbuild` ? `sum_r2_build` : `sum_r2_weak`);
            } else if (round === 3) {
                // Round 3 — Read the evidence & decide go/no-go/pivot.
                // Reading: actionable (segment-level) beats vanity beats ignoring the contradiction.
                if (d.read === `actionable`) {
                    learningDelta += 8; coachKey = `coach_r3_actionable`;
                } else if (d.read === `vanity`) {
                    learningDelta -= 6; tractionDelta += 1; ds.vanity = true; coachKey = `coach_r3_vanity`;
                } else {
                    learningDelta -= 7; coachKey = `coach_r3_ignore`;
                }

                // The correct call depends on whether real traction has been earned.
                // Pivot (refocus on the converting segment) is the textbook lean move while runway remains;
                // kill is right if learning/traction are weak; persevere only if traction already clears the bar.
                const tractionStrong = ds.traction >= 28;
                if (d.decision === `pivot`) {
                    learningDelta += 8; tractionDelta += 8; coachKey = `coach_r3_pivot`;
                } else if (d.decision === `kill`) {
                    // A kill ends the venture: capital is returned, the runway stops burning, and
                    // traction cannot keep climbing toward the fundable bar. The discipline earns learning.
                    ds.killed = true;
                    if (!tractionStrong) { learningDelta += 7; coachKey = `coach_r3_killgood`; }
                    else { learningDelta -= 3; coachKey = `coach_r3_killearly`; }
                    burn = 0;   // no more team burn once the plug is pulled
                } else if (d.decision === `persevere`) {
                    if (tractionStrong) { learningDelta += 5; tractionDelta += 6; coachKey = `coach_r3_persevere_ok`; }
                    else { learningDelta -= 8; tractionDelta -= 6; ds.sunkDriven = true; coachKey = `coach_r3_perseverebad`; }
                }

                // Sunk-cost weight — deciding on money already spent rather than remaining runway.
                if (d.sunk >= 60) { learningDelta -= 6; ds.sunkDriven = true; if (coachKey === `coach_default`) coachKey = `coach_r3_sunk`; }
                else if (d.sunk <= 25) { learningDelta += 4; }

                // Ring-fencing runway to act on the decision.
                if (d.reserve >= 1.5 && d.reserve <= 4) { tractionDelta += 3; }
                else if (d.reserve < 1) { learningDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r3_noreserve` : coachKey; }

                summaryKey = (d.read === `actionable` && (d.decision === `pivot` || (d.decision === `kill` && !tractionStrong) || (d.decision === `persevere` && tractionStrong)) && d.sunk <= 40) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Round 4 — Recover & pitch the gate.
                if (d.plan === `evidenceled`) {
                    learningDelta += 8; tractionDelta += 6; coachKey = `coach_r4_evidenceled`;
                } else if (d.plan === `scaleanyway`) {
                    learningDelta -= 6; tractionDelta -= 5; coachKey = `coach_r4_scaleanyway`;
                } else if (d.plan === `threemonths`) {
                    learningDelta -= 7; tractionDelta -= 3; burn += 1.0; ds.sunkDriven = true; coachKey = `coach_r4_threemonths`;
                }

                // What you pitch — learning story vs demo vs sponsor's word.
                if (d.pitch === `learning`) {
                    learningDelta += 7; tractionDelta += 3;
                    if (d.plan === `evidenceled`) coachKey = `coach_r4_pitchlearning`;
                } else if (d.pitch === `demo`) {
                    learningDelta -= 3; ds.vanity = true; coachKey = `coach_r4_demo`;
                } else if (d.pitch === `sponsorword`) {
                    learningDelta -= 6; ds.vanity = true; coachKey = `coach_r4_sponsorword`;
                }

                // Holding the gate against an executive demand.
                if (d.sponsor === `hold`) { learningDelta += 5; tractionDelta += 3; }
                else if (d.sponsor === `split`) { learningDelta -= 2; }
                else if (d.sponsor === `cave`) { learningDelta -= 7; tractionDelta -= 5; coachKey = `coach_r4_cave`; }

                // Conviction nudge.
                learningDelta += Math.round((d.conviction - 50) / 12);

                // A killed venture is shut down: the pitch is a clean harvest of learning, not a
                // scale-up — traction cannot keep climbing toward the fundable bar after a kill.
                if (ds.killed) { tractionDelta = Math.min(0, tractionDelta); burn = 0; }

                summaryKey = (d.plan === `evidenceled` && d.pitch === `learning` && d.sponsor === `hold`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // --- Resource accounting ---
            // RotaSmart's long enterprise sales cycle keeps eating runway every active round.
            if (ds.rotaDrag && !ds.killed && round >= 2) burn += 0.5;

            ds.budgetUsed = Math.round(Math.min(this.BUDGET_CAP, ds.budgetUsed + spend) * 10) / 10;
            ds.runway = Math.round(Math.max(0, ds.runway - burn) * 10) / 10;
            if (ds.runway <= 1.0 && !ds.killed) ds.burnedOut = true;

            // --- KPI movement (start low, keep headroom so every wrong lever still registers) ---
            ds.learning = Math.max(0, Math.min(100, ds.learning + learningDelta));
            ds.traction = Math.max(0, Math.min(100, ds.traction + tractionDelta));

            // Burned-out runway caps what learning/traction can mean: no runway left to act on it.
            if (ds.burnedOut) {
                ds.learning = Math.max(0, ds.learning - 6);
                ds.traction = Math.max(0, ds.traction - 8);
                if (round >= 3 && coachKey === `coach_default`) coachKey = `coach_runway_gone`;
            }

            ds.learningHistory.push(Math.round(ds.learning));
            ds.tractionHistory.push(Math.round(ds.traction));
            ds.runwayHistory.push(ds.runway);
            ds.performance = { overallScore: this._composite(ds) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });
            }, 500);

            return {
                period: state.currentPeriod,
                learning: Math.round(ds.learning),
                learningDelta: Math.round(learningDelta),
                traction: Math.round(ds.traction),
                tractionDelta: Math.round(tractionDelta),
                runway: ds.runway,
                budgetUsed: ds.budgetUsed,
                vanity: ds.vanity,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`learningDisplay`, `domainState.learning`, (v) => Math.round(v));
            uiManager.bind(`tractionDisplay`, `domainState.traction`, (v) => {
                const card = document.querySelector(`.ventursim-card-traction`);
                if (card) card.classList.toggle(`ventursim-traction-hit`, Number(v) >= this.PILOT_BAR);
                return Math.round(v);
            });
            uiManager.bind(`runwayDisplay`, `domainState.runway`, (v) => {
                const card = document.querySelector(`.ventursim-card-runway`);
                if (card) card.classList.toggle(`ventursim-runway-low`, Number(v) <= 2.0);
                return Number(v).toFixed(1);
            });
            uiManager.bind(`budgetCardDisplay`, `domainState.budgetUsed`, (v) => {
                const card = document.querySelector(`.ventursim-card-budget`);
                if (card) card.classList.toggle(`ventursim-budget-over`, Number(v) >= this.BUDGET_CAP - 0.0001);
                return `R$` + this._fmtM(Number(v)) + `M`;
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => `R$` + this._fmtM(Number(v)) + `M / R$9,0M`);

            // Rigor slider readout.
            const rg = document.getElementById(`rigorInput`);
            const rgReadout = document.getElementById(`rigorReadout`);
            if (rg && rgReadout) {
                rgReadout.textContent = rg.value;
                rg.addEventListener(`input`, function() { rgReadout.textContent = rg.value; });
            }

            // Sunk-cost slider readout.
            const sk = document.getElementById(`sunkInput`);
            const skReadout = document.getElementById(`sunkReadout`);
            if (sk && skReadout) {
                skReadout.textContent = sk.value;
                sk.addEventListener(`input`, function() { skReadout.textContent = sk.value; });
            }
        }

        _fmtM(v) {
            // R$ uses comma as the decimal separator.
            return (Math.round(v * 10) / 10).toFixed(1).replace(`.`, `,`);
        }

        _composite(ds) {
            const learning = Math.round(ds.learning);
            const traction = Math.round(ds.traction);
            const runway = ds.runway;
            const runwayPct = Math.min(100, (runway / this.START_RUNWAY) * 100);
            return ds.killed
                ? Math.round(Math.min(100, learning) * 0.55 + runwayPct * 0.45)
                : Math.round(Math.min(100, learning) * 0.45 + traction * 0.40 + runwayPct * 0.15);
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

