        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.learningHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                ventureChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.learningHistory },
                        { data: ds.tractionHistory },
                        { data: ds.runwayHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const learning = Math.round(ds.learning);
            const traction = Math.round(ds.traction);
            const runway = ds.runway;

            const runwayPct = Math.min(100, (runway / this.START_RUNWAY) * 100);
            const clearedBar = traction >= this.PILOT_BAR;
            // A "go" verdict (fundable) is only available if the venture was NOT killed.
            const validated = !ds.killed && learning >= 60 && clearedBar;
            // A disciplined kill: pulled the plug on a venture that wasn't clearing the bar,
            // before burning the runway, with honest learning to harvest.
            const disciplinedKill = ds.killed && learning >= 50 && runway >= 2 && !ds.burnedOut;
            const vanity = ds.vanity && !validated && !disciplinedKill;
            // Composite: a kill is scored on learning + capital preserved (runway), not on traction
            // it deliberately stopped chasing; a go/pivot is scored on learning + traction + runway.
            const composite = this._composite(ds);

            let performanceKey = `grade_latefail`;
            if (validated && composite >= 68 && !ds.sunkDriven) performanceKey = `grade_fundable`;
            else if (validated) performanceKey = `grade_validated`;
            else if (disciplinedKill) performanceKey = `grade_kill`;
            else if (vanity) performanceKey = `grade_vanity`;
            else if (ds.burnedOut) performanceKey = `grade_burned`;
            else if (composite >= 45) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (validated && !ds.sunkDriven) insights.push(window.mySimulation.t(`insight_fundable`));
            else if (validated) insights.push(window.mySimulation.t(`insight_validated`));
            else if (disciplinedKill) insights.push(window.mySimulation.t(`insight_kill`));
            else if (vanity) insights.push(window.mySimulation.t(`insight_vanity`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.builtFull) insights.push(window.mySimulation.t(`insight_built`));
            if (ds.burnedOut) insights.push(window.mySimulation.t(`insight_burned`));
            if (ds.sunkDriven) insights.push(window.mySimulation.t(`insight_sunk`));
            if (ds.fundedIdea === `rotasmart`) insights.push(window.mySimulation.t(`insight_rotasmart`));
            if (ds.fundedIdea === `entregaflex` && !validated) insights.push(window.mySimulation.t(`insight_sponsor`));
            if (validated && traction >= 55) insights.push(window.mySimulation.t(`insight_strongtraction`));

            return {
                learning: learning,
                traction: traction,
                runway: runway,
                clearedBar: clearedBar,
                validated: validated,
                vanity: vanity,
                composite: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                sound: (validated || disciplinedKill),
                sunkDriven: ds.sunkDriven,
                burnedOut: ds.burnedOut,
                killed: ds.killed,
                budgetUsed: ds.budgetUsed,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const metBadge = s.sound
                ? `<span class="ventursim-cm-badge ventursim-cm-yes">` + T(`cm_sound`) + `</span>`
                : `<span class="ventursim-cm-badge ventursim-cm-no">` + T(`cm_notsound`) + `</span>`;
            let failBadges = ``;
            if (s.vanity) failBadges += ` <span class="ventursim-cm-badge ventursim-cm-fail">` + T(`cm_vanity`) + `</span>`;
            if (s.sunkDriven) failBadges += ` <span class="ventursim-cm-badge ventursim-cm-fail">` + T(`cm_sunk`) + `</span>`;
            if (s.burnedOut) failBadges += ` <span class="ventursim-cm-badge ventursim-cm-fail">` + T(`cm_burned`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const runwayTxt = (Math.round(Number(s.runway || 0) * 10) / 10) + T(`cm_mo`);
            const metrics = ``
                + `<div class="ventursim-cm-metric"><span class="ventursim-cm-mv">` + Math.round(s.learning || 0) + `</span><span class="ventursim-cm-ml">` + T(`cm_m_learning`) + `</span></div>`
                + `<div class="ventursim-cm-metric"><span class="ventursim-cm-mv">` + Math.round(s.traction || 0) + `</span><span class="ventursim-cm-ml">` + T(`cm_m_traction`) + `</span></div>`
                + `<div class="ventursim-cm-metric"><span class="ventursim-cm-mv">` + runwayTxt + `</span><span class="ventursim-cm-ml">` + T(`cm_m_runway`) + `</span></div>`
                + `<div class="ventursim-cm-metric"><span class="ventursim-cm-mv">R$` + (Math.round(Number(s.budgetUsed || 0) * 10) / 10) + `M</span><span class="ventursim-cm-ml">` + T(`cm_m_budget`) + `</span></div>`;
            return ``
                + `<div class="ventursim-completion">`
                +   `<div class="ventursim-cm-head">`
                +     `<div class="ventursim-cm-score">` + score + `<span class="ventursim-cm-score-max">/100</span></div>`
                +     `<div class="ventursim-cm-grade">` + grade + ` ` + metBadge + failBadges + `</div>`
                +   `</div>`
                +   `<div class="ventursim-cm-metrics">` + metrics + `</div>`
                +   `<div class="ventursim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="ventursim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.burnedOut && state.currentPeriod < this.ROUNDS.length) return window.mySimulation.t(`hint_runway`);
            if (ds.builtFull && state.currentPeriod >= 2) return window.mySimulation.t(`hint_built`);
            if (ds.vanity) return window.mySimulation.t(`hint_vanity`);
            if (ds.sunkDriven) return window.mySimulation.t(`hint_sunk`);
            if (state.currentPeriod >= 3 && ds.traction < this.PILOT_BAR) return window.mySimulation.t(`hint_behind`);
            if (ds.learning >= 60 && ds.traction >= this.PILOT_BAR) return window.mySimulation.t(`hint_strong`);
            return null;
        }

